import fs from 'fs';
import path from 'path';

const specs = [
  'specs/hal-engine-session-resume/spec.md',
  'specs/hal-engine-websocket-protocol/spec.md'
];

for (const specPath of specs) {
  const fullPath = path.resolve('target', specPath);
  if (!fs.existsSync(fullPath)) continue;

  let content = fs.readFileSync(fullPath, 'utf-8');
  const linkRegex = /\[validated by: ([^\]]+)\]\(([^#)]+)#L(\d+)\)/g;

  const newContent = content.replace(linkRegex, (match, title, testFile, line) => {
    const testPath = path.resolve(path.dirname(fullPath), testFile);
    if (!fs.existsSync(testPath)) return match;

    const testContent = fs.readFileSync(testPath, 'utf-8');
    const lines = testContent.split('\n');

    // Search for the title in the test file
    let foundLine = -1;
    for (let i = 0; i < lines.length; i++) {
      if (lines[i].includes(title)) {
        foundLine = i + 1;
        break;
      }
    }

    if (foundLine !== -1) {
      return `[validated by: ${title}](${testFile}#L${foundLine})`;
    }
    return match;
  });

  if (newContent !== content) {
    fs.writeFileSync(fullPath, newContent);
    console.log(`Updated ${specPath}`);
  }
}

